{"for": "Software Engineers", "goal": "To quickly identify and fix potential security vulnerabilities in their codebase.", "steps": [
  {"name": "pii-audit", "does": "Identifies sensitive personal information and potentially dangerous code patterns within the files."},
  {"name": "risky-code", "does": "Lists lines of code matching known-dangerous patterns, providing immediate alerts."},
  {"name": "hook-impact", "does": "Provides a hook to hand the assistant every place in your files that names what it's about to change, by file and line."},
  {"name": "ci", "does": "Runs checks on the repo’s code as verdict rows on a kernel record"},
  {"name": "shell-history", "does": "Traces the context of communication alongside their actions"}
]}
